import 'package:flutter/material.dart';
import '../../core/services/sharetrip_local_store.dart';

class DriverProfileEditorPage extends StatefulWidget {
  const DriverProfileEditorPage({super.key});
  @override State<DriverProfileEditorPage> createState() => _DriverProfileEditorPageState();
}
class _DriverProfileEditorPageState extends State<DriverProfileEditorPage> {
  final _name = TextEditingController(), _email = TextEditingController(), _phone = TextEditingController(), _model = TextEditingController(), _plate = TextEditingController();
  String _type = 'Shuttle'; bool _loading = true;
  @override void initState(){ super.initState(); ShareTripLocalStore.getDriverProfile().then((p){ if(!mounted)return; p ??= {}; _name.text='${p['name']??''}'; _email.text='${p['email']??''}'; _phone.text='${p['phone']??''}'; _model.text='${p['vehicleModel']??''}'; _plate.text='${p['plate']??''}'; _type='${p['vehicleType']??'Shuttle'}'; setState(()=>_loading=false); }); }
  @override void dispose(){for(final c in [_name,_email,_phone,_model,_plate]){c.dispose();}super.dispose();}
  Future<void> _save() async { await ShareTripLocalStore.saveDriverProfile({'name':_name.text.trim(),'email':_email.text.trim(),'phone':_phone.text.trim(),'vehicleType':_type,'vehicleModel':_model.text.trim(),'plate':_plate.text.trim()}); if(mounted){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Driver profile saved on this device.'))); Navigator.pop(context,true);} }
  Widget _field(String label,TextEditingController c,{TextInputType? keyboard})=>Padding(padding:const EdgeInsets.only(bottom:12),child:TextField(controller:c,keyboardType:keyboard,decoration:InputDecoration(labelText:label,border:const OutlineInputBorder())));
  @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Edit Driver Profile')),body:_loading?const Center(child:CircularProgressIndicator()):ListView(padding:const EdgeInsets.all(18),children:[_field('Full name',_name),_field('School email',_email,keyboard:TextInputType.emailAddress),_field('Contact number',_phone,keyboard:TextInputType.phone),const Text('Vehicle type'),DropdownButtonFormField<String>(value:_type,items:const ['Shuttle','Motorcycle','Tricycle'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>setState(()=>_type=v??_type)),const SizedBox(height:12),_field('Vehicle model / description',_model),_field('Plate number',_plate),FilledButton.icon(onPressed:_save,icon:const Icon(Icons.save),label:const Text('Save profile'))]));
}

class DriverVehicleManagerPage extends StatefulWidget { const DriverVehicleManagerPage({super.key}); @override State<DriverVehicleManagerPage> createState()=>_DriverVehicleManagerPageState(); }
class _DriverVehicleManagerPageState extends State<DriverVehicleManagerPage>{ List<Map<String,dynamic>> _vehicles=[]; bool _loading=true; @override void initState(){super.initState();_load();} Future<void> _load()async{final v=await ShareTripLocalStore.getDriverVehicles();final p=await ShareTripLocalStore.getDriverProfile();if(v.isEmpty&&p!=null&&('${p['vehicleModel']??''}'.isNotEmpty||'${p['plate']??''}'.isNotEmpty)){v.add({'type':p['vehicleType']??'Shuttle','model':p['vehicleModel']??'Registered vehicle','plate':p['plate']??'','primary':true});}if(mounted)setState(()=>_vehicles=v);_loading=false;}
 Future<void> _add()async{final model=TextEditingController(),plate=TextEditingController();String type='Shuttle';final ok=await showDialog<bool>(context:context,builder:(ctx)=>StatefulBuilder(builder:(ctx,ss)=>AlertDialog(title:const Text('Add vehicle'),content:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<String>(value:type,items:const ['Shuttle','Motorcycle','Tricycle'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>ss(()=>type=v??type)),TextField(controller:model,decoration:const InputDecoration(labelText:'Model / description')),TextField(controller:plate,decoration:const InputDecoration(labelText:'Plate number'))]),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('Add'))])));if(ok==true&&model.text.trim().isNotEmpty&&plate.text.trim().isNotEmpty){_vehicles.add({'type':type,'model':model.text.trim(),'plate':plate.text.trim()});await ShareTripLocalStore.saveDriverVehicles(_vehicles);setState((){});}}
 Future<void> _remove(int i)async{_vehicles.removeAt(i);await ShareTripLocalStore.saveDriverVehicles(_vehicles);setState((){});}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('My Vehicles')),floatingActionButton:FloatingActionButton.extended(onPressed:_add,icon:const Icon(Icons.add),label:const Text('Add vehicle')),body:_loading?const Center(child:CircularProgressIndicator()):_vehicles.isEmpty?const Center(child:Text('No additional vehicles saved. Add one to manage your fleet.')):ListView(children:List.generate(_vehicles.length,(i){final v=_vehicles[i];return Card(margin:const EdgeInsets.all(10),child:ListTile(leading:const Icon(Icons.directions_car),title:Text('${v['type']} · ${v['model']}'),subtitle:Text('Plate: ${v['plate']}'),trailing:IconButton(icon:const Icon(Icons.delete_outline),onPressed:()=>_remove(i))));})));}

class DriverNotificationCenterPage extends StatefulWidget { const DriverNotificationCenterPage({super.key}); @override State<DriverNotificationCenterPage> createState()=>_DriverNotificationCenterPageState(); }
class _DriverNotificationCenterPageState extends State<DriverNotificationCenterPage>{List<Map<String,dynamic>> _items=[];bool _loading=true;@override void initState(){super.initState();_load();}Future<void> _load()async{final n=await ShareTripLocalStore.getDriverNotifications();if(mounted)setState(()=>_items=n); _loading=false;}Future<void> _readAll()async{await ShareTripLocalStore.markDriverNotificationsRead();await _load();}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Driver Notifications'),actions:[TextButton(onPressed:_readAll,child:const Text('Read all'))]),body:_loading?const Center(child:CircularProgressIndicator()):_items.isEmpty?const Center(child:Text('No notifications yet. Ride requests and trip updates will appear here.')):ListView.separated(itemCount:_items.length,separatorBuilder:(_,__)=>const Divider(height:1),itemBuilder:(ctx,i){final n=_items[i];return ListTile(leading:CircleAvatar(child:Icon(n['read']==true?Icons.notifications_none:Icons.notifications_active)),title:Text('${n['title']??''}',style:TextStyle(fontWeight:n['read']==true?FontWeight.normal:FontWeight.bold)),subtitle:Text('${n['message']??''}\n${n['time']??''}'),isThreeLine:true,onTap:()async{n['read']=true;await ShareTripLocalStore.markDriverNotificationsRead();setState((){});});}));}

